def stable_matching(proposers, receivers):
    next_index = {p: 0 for p in proposers}
    engaged = {}  # receiver -> proposer
    free = set(proposers.keys())
    receiver_rank = {r: {p: i for i, p in enumerate(prefs)} for r, prefs in receivers.items()}

    while free:
        p = min(free)
        free.remove(p)
        prefs = proposers[p]
        if next_index[p] >= len(prefs):
            continue
        r = prefs[next_index[p]]
        next_index[p] += 1

        if r not in engaged:
            engaged[r] = p
        else:
            current = engaged[r]
            if receiver_rank[r][p] < receiver_rank[r][current]:
                engaged[r] = p
                free.add(current)
                free.add(p)  # p stays, remove below
                free.discard(p)
            else:
                free.add(p)

    return {p: r for r, p in engaged.items()}
